// src/pages/listening/Library.tsx
//
// /listening — real-world listening library index.
//
// Auth-required. Shows all 30 clips grouped by category with
// difficulty + accent filters and per-clip completion checkmarks.
// Audio is generated by a separate background job; until then
// each clip page shows a transcript-only mode.

import React, { useEffect, useMemo, useState } from "react";
import { Link, Navigate } from "react-router-dom";
import { Headphones } from "lucide-react";

import { useAuth } from "@/providers/AuthProvider";
import {
  LISTENING_CLIPS,
  LISTENING_BY_CATEGORY,
  type ListeningAccent,
  type ListeningCategory,
  type ListeningClip,
  type ListeningDifficulty,
} from "@/data/listening/clips";
import { getCompletedClipIds } from "@/services/listeningProgress";

type CategoryFilter = "all" | ListeningCategory;
type DifficultyFilter = "all" | ListeningDifficulty;
type AccentFilter = "all" | ListeningAccent;

const CATEGORY_LABEL: Record<ListeningCategory, { vi: string; en: string }> = {
  restaurant:         { vi: "Nhà hàng",        en: "Restaurant" },
  doctor:             { vi: "Bác sĩ",          en: "Doctor" },
  "customer-service": { vi: "CSKH",            en: "Customer Service" },
  "job-interview":    { vi: "Phỏng vấn",       en: "Interview" },
  casual:             { vi: "Đời thường",      en: "Casual" },
  shopping:           { vi: "Mua sắm",         en: "Shopping" },
  transportation:     { vi: "Di chuyển",       en: "Transportation" },
};

const ACCENT_FLAG: Record<ListeningAccent, string> = {
  us: "🇺🇸",
  uk: "🇬🇧",
  au: "🇦🇺",
  ca: "🇨🇦",
};

const DIFFICULTY_LABEL: Record<ListeningDifficulty, { vi: string; en: string; tone: string }> = {
  beginner:     { vi: "Cơ bản",      en: "Beginner",     tone: "#059669" },
  intermediate: { vi: "Trung cấp",   en: "Intermediate", tone: "#d97706" },
  advanced:     { vi: "Nâng cao",    en: "Advanced",     tone: "#dc2626" },
};

const wrap: React.CSSProperties = {
  width: "100%",
  minHeight: "calc(100vh - 72px)",
  padding: "20px 16px 80px",
  display: "flex",
  justifyContent: "center",
};
const column: React.CSSProperties = {
  width: "100%",
  maxWidth: 880,
  display: "flex",
  flexDirection: "column",
  gap: 16,
};
const cardStyle: React.CSSProperties = {
  border: "1px solid rgba(0,0,0,0.10)",
  borderRadius: 16,
  padding: 16,
  background: "white",
  boxShadow: "0 6px 18px rgba(0,0,0,0.04)",
};

function chipStyle(active: boolean): React.CSSProperties {
  return {
    padding: "6px 12px",
    borderRadius: 9999,
    fontSize: 12,
    fontWeight: 700,
    border: `1px solid ${active ? "#1e3a8a" : "rgba(0,0,0,0.12)"}`,
    background: active ? "#1e3a8a" : "white",
    color: active ? "white" : "#1f2937",
    cursor: "pointer",
  };
}

function ClipCard({
  clip,
  completed,
}: {
  clip: ListeningClip;
  completed: boolean;
}) {
  const difficulty = DIFFICULTY_LABEL[clip.difficulty];
  return (
    <Link
      to={`/listening/${clip.id}`}
      data-testid={`listening-clip-${clip.id}`}
      style={{
        ...cardStyle,
        textDecoration: "none",
        color: "inherit",
        display: "block",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 11, color: "#64748b" }}>
        <span style={{ fontSize: 16 }} aria-hidden>
          {ACCENT_FLAG[clip.accent]}
        </span>
        <span
          style={{
            padding: "2px 8px",
            borderRadius: 9999,
            background: `${difficulty.tone}1a`,
            color: difficulty.tone,
            fontWeight: 800,
          }}
        >
          {difficulty.vi}
        </span>
        <span style={{ fontWeight: 600 }}>{clip.duration_seconds}s</span>
        {completed ? (
          <span
            aria-label="Completed"
            data-testid="listening-clip-completed"
            style={{ marginLeft: "auto", color: "#059669", fontSize: 13, fontWeight: 800 }}
          >
            ✓
          </span>
        ) : null}
      </div>
      <h3 style={{ fontSize: 15, fontWeight: 800, color: "#1f2937", margin: "8px 0 2px" }}>
        {clip.title_vi}
      </h3>
      <div style={{ fontSize: 12, color: "#64748b" }}>{clip.title_en}</div>
    </Link>
  );
}

export default function Library(): React.ReactElement {
  const { user, isLoading: authLoading } = useAuth();
  const [categoryFilter, setCategoryFilter] = useState<CategoryFilter>("all");
  const [difficultyFilter, setDifficultyFilter] = useState<DifficultyFilter>("all");
  const [accentFilter, setAccentFilter] = useState<AccentFilter>("all");
  const [completedIds, setCompletedIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    if (authLoading || !user) return;
    let alive = true;
    void getCompletedClipIds().then((ids) => {
      if (alive) setCompletedIds(ids);
    });
    return () => {
      alive = false;
    };
  }, [authLoading, user]);

  const visibleClips = useMemo(() => {
    let pool: ListeningClip[] =
      categoryFilter === "all"
        ? LISTENING_CLIPS
        : LISTENING_BY_CATEGORY[categoryFilter];
    if (difficultyFilter !== "all") {
      pool = pool.filter((c) => c.difficulty === difficultyFilter);
    }
    if (accentFilter !== "all") {
      pool = pool.filter((c) => c.accent === accentFilter);
    }
    return pool;
  }, [categoryFilter, difficultyFilter, accentFilter]);

  if (authLoading) {
    return (
      <div style={wrap}>
        <p style={{ color: "#64748b", fontSize: 13 }}>Đang tải… · Loading…</p>
      </div>
    );
  }
  if (!user) return <Navigate to="/signin" replace />;

  return (
    <div style={wrap}>
      <div style={column}>
        <header>
          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <Headphones size={22} className="text-sky-700" />
            <h1 style={{ fontSize: 24, fontWeight: 950, margin: 0, color: "rgba(10,10,10,0.94)" }}>
              Thư viện nghe · Listening Library
            </h1>
          </div>
          <p style={{ fontSize: 14, color: "#475569", marginTop: 6 }}>
            30 đoạn hội thoại tiếng Anh thực tế cho người Việt: gọi cà phê, đặt
            khám bác sĩ, gọi tổng đài, phỏng vấn xin việc — không phải tiếng Anh
            sách giáo khoa.
          </p>
          <p style={{ fontSize: 12, color: "#64748b", marginTop: 4 }}>
            30 real-world English clips — coffee orders, doctor calls, customer
            service, interviews. No textbook English.
          </p>
        </header>

        {/* Category filter */}
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
          {(["all", "restaurant", "doctor", "customer-service", "job-interview", "casual", "shopping", "transportation"] as CategoryFilter[]).map((c) => (
            <button
              key={c}
              type="button"
              onClick={() => setCategoryFilter(c)}
              data-testid={`listening-category-${c}`}
              style={chipStyle(categoryFilter === c)}
            >
              {c === "all" ? "Tất cả · All" : CATEGORY_LABEL[c].vi}
            </button>
          ))}
        </div>

        {/* Difficulty + accent filters */}
        <div style={{ display: "flex", flexWrap: "wrap", gap: 12 }}>
          <div style={{ display: "flex", gap: 6 }}>
            <span style={{ fontSize: 11, fontWeight: 700, color: "#64748b", alignSelf: "center" }}>
              Mức · Level:
            </span>
            {(["all", "beginner", "intermediate", "advanced"] as DifficultyFilter[]).map((d) => (
              <button
                key={d}
                type="button"
                onClick={() => setDifficultyFilter(d)}
                data-testid={`listening-difficulty-${d}`}
                style={chipStyle(difficultyFilter === d)}
              >
                {d === "all" ? "Tất cả" : DIFFICULTY_LABEL[d].vi}
              </button>
            ))}
          </div>
          <div style={{ display: "flex", gap: 6 }}>
            <span style={{ fontSize: 11, fontWeight: 700, color: "#64748b", alignSelf: "center" }}>
              Giọng · Accent:
            </span>
            {(["all", "us", "uk", "au", "ca"] as AccentFilter[]).map((a) => (
              <button
                key={a}
                type="button"
                onClick={() => setAccentFilter(a)}
                data-testid={`listening-accent-${a}`}
                style={chipStyle(accentFilter === a)}
              >
                {a === "all" ? "Tất cả" : `${ACCENT_FLAG[a]} ${a.toUpperCase()}`}
              </button>
            ))}
          </div>
        </div>

        <div style={{ fontSize: 12, color: "#64748b" }}>
          Hiển thị {visibleClips.length} / {LISTENING_CLIPS.length} đoạn
        </div>

        <ul
          style={{
            listStyle: "none",
            padding: 0,
            margin: 0,
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))",
            gap: 12,
          }}
        >
          {visibleClips.map((clip) => (
            <li key={clip.id}>
              <ClipCard clip={clip} completed={completedIds.has(clip.id)} />
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
